"""Stage 24.6 runner orchestrator tests.

Pins:

  * Runner invokes all five surfaces (compute_budget, priority_fee,
    jito_tip, router_fee, execution_quality) once per input row.
  * Deterministic input ordering by ``(input_id, payload_hash)``.
  * Empty input returns empty result tuples and a stable manifest
    shape.
  * Typed ``Stage24Error`` from a decoder converts to a
    deterministic rejection record.
  * Untyped exceptions propagate.
  * ``created_at_utc`` is injected, never generated by the runner.
  * Router-fee output never contains a ``DECODED`` row at Stage
    24.6 (Path B lock).
  * No confirmed ``AXIOM_GLOBAL_FEE`` fee_source appears in any
    output row.
"""

from __future__ import annotations

from types import MappingProxyType

import pytest

from PHX2.stage24.constants import (
    DECODER_STATUSES,
    DEFAULT_THRESHOLD_VERSION,
    FEE_SOURCES,
    PRIMITIVE_FAMILIES,
    PRIMITIVE_FAMILY_COMPUTE_BUDGET,
    PRIMITIVE_FAMILY_EXECUTION_QUALITY,
    PRIMITIVE_FAMILY_JITO_TIP,
    PRIMITIVE_FAMILY_PRIORITY_FEE,
    PRIMITIVE_FAMILY_ROUTER_FEE,
    STAGE24_REJECTION_REASON_DECODER_TYPED_ERROR,
)
from PHX2.stage24.errors import Stage24DecoderError
from PHX2.stage24.models import Stage24RunnerResult
from PHX2.stage24.runner import (
    Stage24RejectionRecord,
    default_decoder_names,
    run_stage24_decoders,
)
from PHX2.tests.stage24.fixtures.builders import (
    FIXED_CLOCK_UTC,
    make_axiom_flashx8_instruction,
    make_compute_budget_set_unit_limit_instruction,
    make_compute_budget_set_unit_price_instruction,
    make_execution_input,
    make_jito_tip_instruction,
    make_router_like_execution_input,
)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _two_inputs():
    plain = make_execution_input(
        signature="sig_runner_plain_001",
        top_level_instructions=(
            make_compute_budget_set_unit_limit_instruction(units=200_000),
            make_compute_budget_set_unit_price_instruction(
                micro_lamports_per_compute_unit=1_000,
            ),
        ),
        meta=MappingProxyType(
            {"compute_units_consumed": 50_000, "fee": 5000}
        ),
    )
    router_candidate = make_router_like_execution_input(
        signature="sig_runner_router_001",
        top_level_instructions=(make_axiom_flashx8_instruction(),),
    )
    return plain, router_candidate


# ---------------------------------------------------------------------------
# Decoder name list
# ---------------------------------------------------------------------------


def test_default_decoder_names_returns_locked_five_tuple():
    names = default_decoder_names()
    assert names == (
        "compute_budget",
        "priority_fee",
        "jito_tip",
        "router_fee",
        "execution_quality",
    )


# ---------------------------------------------------------------------------
# Runner invokes all five surfaces
# ---------------------------------------------------------------------------


def test_runner_emits_one_row_per_family_per_input():
    plain, router_candidate = _two_inputs()
    result, rejections = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    assert rejections == ()
    assert len(result.compute_budget_results) == 2
    assert len(result.priority_fee_results) == 2
    assert len(result.jito_tip_results) == 2
    assert len(result.router_fee_results) == 2
    assert len(result.execution_quality_results) == 2


def test_runner_emits_five_primitives_per_input():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    # Five primitive families per input row.
    assert len(result.execution_primitives) == 10


def test_runner_primitives_cover_every_family():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    families = {p.primitive_family for p in result.execution_primitives}
    assert families == set(PRIMITIVE_FAMILIES)


# ---------------------------------------------------------------------------
# Deterministic ordering
# ---------------------------------------------------------------------------


def test_runner_orders_results_deterministically():
    plain, router_candidate = _two_inputs()
    result_a, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    result_b, _ = run_stage24_decoders(
        execution_inputs=(router_candidate, plain),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    # Same result tuples regardless of input order.
    assert result_a.compute_budget_results == result_b.compute_budget_results
    assert result_a.priority_fee_results == result_b.priority_fee_results
    assert result_a.jito_tip_results == result_b.jito_tip_results
    assert result_a.router_fee_results == result_b.router_fee_results
    assert (
        result_a.execution_quality_results
        == result_b.execution_quality_results
    )


def test_runner_primitives_are_deterministic_across_runs():
    plain, router_candidate = _two_inputs()
    result_a, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    result_b, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    a_hashes = tuple(p.primitive_hash for p in result_a.execution_primitives)
    b_hashes = tuple(p.primitive_hash for p in result_b.execution_primitives)
    assert a_hashes == b_hashes


# ---------------------------------------------------------------------------
# Empty input behavior
# ---------------------------------------------------------------------------


def test_empty_input_returns_empty_result():
    result, rejections = run_stage24_decoders(
        execution_inputs=(),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    assert isinstance(result, Stage24RunnerResult)
    assert result.compute_budget_results == ()
    assert result.priority_fee_results == ()
    assert result.jito_tip_results == ()
    assert result.router_fee_results == ()
    assert result.execution_quality_results == ()
    assert result.execution_primitives == ()
    assert result.input_count == 0
    assert result.input_rejection_count == 0
    assert rejections == ()


# ---------------------------------------------------------------------------
# Typed Stage24Error converts to rejection
# ---------------------------------------------------------------------------


def test_typed_stage24_error_in_decoder_becomes_rejection(monkeypatch):
    import PHX2.stage24.runner as runner_mod

    def _bad_compute_budget(execution_input):
        raise Stage24DecoderError(
            "synthetic decoder typed failure"
        )

    monkeypatch.setattr(
        runner_mod, "decode_compute_budget", _bad_compute_budget
    )
    plain, _ = _two_inputs()
    result, rejections = run_stage24_decoders(
        execution_inputs=(plain,),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    # Compute-budget result tuple is empty because the decoder
    # raised. Other decoders still emit their results.
    assert result.compute_budget_results == ()
    # Priority fee depends on compute_budget so it's also absent.
    assert result.priority_fee_results == ()
    # Other surfaces still ran.
    assert len(result.jito_tip_results) == 1
    assert len(result.router_fee_results) == 1
    assert len(result.execution_quality_results) == 1
    # Rejection recorded.
    assert len(rejections) == 1
    rej = rejections[0]
    assert isinstance(rej, Stage24RejectionRecord)
    assert rej.decoder_name == "compute_budget"
    assert rej.primitive_family == PRIMITIVE_FAMILY_COMPUTE_BUDGET
    assert rej.reason == STAGE24_REJECTION_REASON_DECODER_TYPED_ERROR
    assert rej.error_class == "Stage24DecoderError"


def test_typed_stage24_error_does_not_swallow_other_decoders(monkeypatch):
    import PHX2.stage24.runner as runner_mod

    def _bad_jito_tip(execution_input):
        raise Stage24DecoderError(
            "synthetic jito-tip typed failure"
        )

    monkeypatch.setattr(
        runner_mod, "decode_jito_tip", _bad_jito_tip
    )
    plain, _ = _two_inputs()
    result, rejections = run_stage24_decoders(
        execution_inputs=(plain,),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    assert len(result.compute_budget_results) == 1
    assert len(result.priority_fee_results) == 1
    assert result.jito_tip_results == ()
    assert len(result.router_fee_results) == 1
    assert len(result.execution_quality_results) == 1
    assert len(rejections) == 1
    assert rejections[0].decoder_name == "jito_tip"


# ---------------------------------------------------------------------------
# Untyped exceptions propagate
# ---------------------------------------------------------------------------


def test_untyped_exception_in_decoder_propagates(monkeypatch):
    import PHX2.stage24.runner as runner_mod

    def _exploding_decoder(execution_input):
        raise RuntimeError("not a Stage24Error")

    monkeypatch.setattr(
        runner_mod, "decode_compute_budget", _exploding_decoder
    )
    plain, _ = _two_inputs()
    with pytest.raises(RuntimeError, match="not a Stage24Error"):
        run_stage24_decoders(
            execution_inputs=(plain,),
            created_at_utc=FIXED_CLOCK_UTC,
        )


# ---------------------------------------------------------------------------
# Injected clock
# ---------------------------------------------------------------------------


def test_runner_uses_injected_created_at_utc():
    plain, _ = _two_inputs()
    pinned = "2026-05-20T12:34:56Z"
    result, _ = run_stage24_decoders(
        execution_inputs=(plain,),
        created_at_utc=pinned,
    )
    assert result.created_at_utc == pinned
    for primitive in result.execution_primitives:
        assert primitive.created_at_utc == pinned


def test_runner_rejects_empty_created_at_utc():
    plain, _ = _two_inputs()
    with pytest.raises(ValueError):
        run_stage24_decoders(
            execution_inputs=(plain,),
            created_at_utc="",
        )


def test_runner_rejects_non_string_created_at_utc():
    plain, _ = _two_inputs()
    with pytest.raises(ValueError):
        run_stage24_decoders(
            execution_inputs=(plain,),
            created_at_utc=None,  # type: ignore[arg-type]
        )


def test_runner_rejects_non_tuple_execution_inputs():
    plain, _ = _two_inputs()
    with pytest.raises(TypeError):
        run_stage24_decoders(
            execution_inputs=[plain],  # type: ignore[arg-type]
            created_at_utc=FIXED_CLOCK_UTC,
        )


# ---------------------------------------------------------------------------
# Router fee stays candidate-only
# ---------------------------------------------------------------------------


def test_router_fee_results_never_contain_decoded_status():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    for rfr in result.router_fee_results:
        assert rfr.decoder_status != "DECODED"
        assert rfr.amount_lamports is None
        assert rfr.amount_token is None


def test_no_axiom_global_fee_appears_in_any_result():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    for rfr in result.router_fee_results:
        assert rfr.fee_source != "AXIOM_GLOBAL_FEE"
        assert rfr.fee_source != "ROUTER_FEE"
    for primitive in result.execution_primitives:
        if primitive.primitive_family == PRIMITIVE_FAMILY_ROUTER_FEE:
            assert primitive.fee_source != "AXIOM_GLOBAL_FEE"
            assert primitive.fee_source != "ROUTER_FEE"


def test_execution_quality_realized_router_fee_is_always_none():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    for eqr in result.execution_quality_results:
        assert eqr.realized_router_fee_lamports is None


# ---------------------------------------------------------------------------
# Result-row closed-set integrity
# ---------------------------------------------------------------------------


def test_every_result_uses_closed_set_decoder_status():
    plain, router_candidate = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    all_results: list = []
    all_results.extend(result.compute_budget_results)
    all_results.extend(result.priority_fee_results)
    all_results.extend(result.jito_tip_results)
    all_results.extend(result.router_fee_results)
    all_results.extend(result.execution_quality_results)
    for r in all_results:
        assert r.decoder_status in DECODER_STATUSES
        assert r.fee_source in FEE_SOURCES


def test_runner_counts_match_decoder_outputs():
    plain, router_candidate = _two_inputs()
    result, rejections = run_stage24_decoders(
        execution_inputs=(plain, router_candidate),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    assert result.input_count == 2
    assert result.input_rejection_count == len(rejections)


# ---------------------------------------------------------------------------
# With Jito tip + router candidate combined input
# ---------------------------------------------------------------------------


def test_runner_handles_jito_tip_plus_router_candidate_input():
    execution_input = make_router_like_execution_input(
        top_level_instructions=(
            make_axiom_flashx8_instruction(),
            make_jito_tip_instruction(lamports=15_000),
        ),
    )
    result, _ = run_stage24_decoders(
        execution_inputs=(execution_input,),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    assert len(result.jito_tip_results) == 1
    assert result.jito_tip_results[0].decoder_status == "DECODED"
    assert result.jito_tip_results[0].amount_lamports == 15_000
    assert len(result.router_fee_results) == 1
    assert (
        result.router_fee_results[0].decoder_status == "DECODE_UNCONFIRMED"
    )


# ---------------------------------------------------------------------------
# Threshold version axis is the locked observe-only token
# ---------------------------------------------------------------------------


def test_compute_budget_results_carry_observe_only_threshold_version():
    plain, _ = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain,),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    for r in result.compute_budget_results:
        assert r.threshold_version == DEFAULT_THRESHOLD_VERSION


# ---------------------------------------------------------------------------
# Primitive families counters
# ---------------------------------------------------------------------------


def test_primitive_family_counts_per_input():
    plain, _ = _two_inputs()
    result, _ = run_stage24_decoders(
        execution_inputs=(plain,),
        created_at_utc=FIXED_CLOCK_UTC,
    )
    counts: dict[str, int] = {}
    for p in result.execution_primitives:
        counts[p.primitive_family] = counts.get(p.primitive_family, 0) + 1
    assert counts == {
        PRIMITIVE_FAMILY_COMPUTE_BUDGET: 1,
        PRIMITIVE_FAMILY_PRIORITY_FEE: 1,
        PRIMITIVE_FAMILY_JITO_TIP: 1,
        PRIMITIVE_FAMILY_ROUTER_FEE: 1,
        PRIMITIVE_FAMILY_EXECUTION_QUALITY: 1,
    }
